start = next(iter(green))
visited = set()
queue = deque([start])
visited.add(start)
while queue:
    node = queue.popleft()
    for nb in adj[node]:
        if nb not in visited:
            visited.add(nb)
            queue.append(nb)

print('\nConnected:', visited == green)
deg1_nodes = [cell for cell in adj if len(adj[cell]) < 2]
