def hamiltonian_cycle(adj, nodes):
    nodes = list(nodes)
    n = len(nodes)
    node_idx = {node: i for i, node in enumerate(nodes)}

    path = [nodes[0]]
    visited = {nodes[0]}

    def backtrack():
        if len(path) == n:
            if nodes[0] in [nb for nb in adj[path[-1]]]:
                return True
            return False

        current = path[-1]
        for nb in adj[current]:
            if nb not in visited:
                visited.add(nb)
                path.append(nb)
                if backtrack():
                    return True
                path.pop()
                visited.remove(nb)
        return False

    return backtrack()

if visited == green and not deg1_nodes:
